/** User guild settings object. Fluxer's documentation: https://docs.fluxer.com/http-api/users/settings/#user-guild-settings-object */
interface UserGuildSettingsObject {
    /** The ID of the guild, or null for DM settings */
    readonly guild_id: string | null
    /** The default notification level */
    readonly message_notifications: number
    /** Whether the guild or DMs are muted */
    readonly muted: boolean
    /** The mute configuration, or null when none is stored */
    readonly mute_config: GuildMuteConfigurationObject | null
    /** Whether push notifications are enabled */
    readonly mobile_push: boolean
    /** Whether `@everyone` mentions are suppressed */
    readonly suppress_everyone: boolean
    /** Whether role mentions are suppressed */
    readonly suppress_roles: boolean
    /** Whether muted channels are hidden */
    readonly hide_muted_channels: boolean
    /** The per-channel overrides, or null when none are set */
    readonly channel_overrides: { readonly [key: string]: ChannelNotificationOverrideObject } | null
    /** The default notification level for unread badges, or null to follow `message_notifications` */
    readonly unread_badges: number | null
    /** The revision of this settings object */
    readonly version: number
}
